(7481008, 1189963, 163081, '<td valign="top">The picture is ok, but if it was sharper, it would stand out more. A 5 from me.</td>', 'The picture is ok, but if it was sharper, it would stand out more. A 5 from me.', '2016-11-04 17:54:06.000000', NULL, 1),
(7481009, 1189692, 163081, '<td valign="top">I want to see this picture with a different processing. It looks flat. A 5 from me</td>', 'I want to see this picture with a different processing. It looks flat. A 5 from me', '2016-11-04 17:56:25.000000', NULL, 1),
(7481037, 1189604, 163081, '<td valign="top">This picture has much potential to be better. Nothing is clear. out of focus, and weird tones. I am generous and give you a 5.</td>', 'This picture has much potential to be better. Nothing is clear. out of focus, and weird tones. I am generous and give you a 5.', '2016-11-04 23:39:30.000000', NULL, 1),
(7481038, 1189808, 163081, '<td valign="top">I like the picture but there are few things that bother me. most of all the choice to process the upper half as a watercolor painting and not the lower part.(or vice versa) The water color is unnatural blue. The vignetting is not needed in this type of picture. I also don''t really know what''s the main subject. A 6 from me.</td>', 'I like the picture but there are few things that bother me. most of all the choice to process the upper half as a watercolor painting and not the lower part.(or vice versa) The water color is unnatural blue. The vignetting is not needed in this type of picture. I also don''t really know what''s the main subject. A 6 from me.', '2016-11-04 23:44:59.000000', NULL, 1),
(7481071, 1189977, 69324, '<td valign="top">Great location, slightly overprocessed for my tastes though.</td>', 'Great location, slightly overprocessed for my tastes though.', '2016-11-05 12:11:19.000000', NULL, 1),
