(7481360, 1189692, 180710, '<td valign="top">I wish the sky and trees were underexposed to give greater contrast and attention to the building and pump.</td>', 'I wish the sky and trees were underexposed to give greater contrast and attention to the building and pump.', '2016-11-07 09:31:47.000000', NULL, 1),
